from functools import lru_cache
# mask test
rows=['0110110','1111110','0110100','0011100']
S={(r,c) for r,line in enumerate(rows) for c,x in enumerate(line) if x=='1'}
# Tiles square color1; L missing corners colors: TL=2, BL=3, TR=4, BR=5
shapes={1:{(0,0),(0,1),(1,0),(1,1)},2:{(0,1),(1,0),(1,1)},3:{(0,0),(0,1),(1,1)},4:{(0,0),(1,0),(1,1)},5:{(0,0),(0,1),(1,0)}}
tiles=[]
for col,shape in shapes.items():
 for r in range(4):
  for c in range(6):
   t={(r+dr,c+dc) for dr,dc in shape}
   if t<=S: tiles.append((col,t))
@lru_cache(None)
def solve(rem):
 rem=set(rem)
 if not rem:return [()]
 p=min(rem)
 out=[]
 for col,t in tiles:
  if p in t and t<=rem:
   for rest in solve(tuple(sorted(rem-t))): out.append(((col,t),)+rest)
 return out
sols=solve(tuple(sorted(S)))
print('occupied',len(S),'solutions',len(sols))
for i,sol in enumerate(sols[:20]):
 print('sol',i,[(c,sorted(t)) for c,t in sol])
 grid=[[0]*7 for _ in range(4)]
 for col,t in sol:
  for r,c in t:grid[r][c]=col
 print(*grid,sep='\n')

from itertools import product
cells={(1,2),(1,3),(1,5),(1,6)} | {(2,c) for c in range(1,7)} | {(3,2),(3,3),(3,5)} | {(4,3),(4,4),(4,5)}
print(len(cells), sorted(cells))
# possible pieces wholly in shape: 2x2 square; L shape as 2x2 missing corner
pieces=[]
for r in range(1,4):
 for c in range(1,6):
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if box<=cells: pieces.append(('square',r,c,box))
  for missing in box:
   p=box-{missing}
   if p<=cells: pieces.append(('L',r,c,missing,p))
# enumerate exact cover using one square and 4 Ls, optionally all L orientations
bycell={x:[] for x in cells}
for p in pieces:
 for x in p[-1]: bycell[x].append(p)
sol=[]
def rec(rem, chosen, sq):
 if not rem:
  if sq==1: sol.append(chosen)
  return
 x=min(rem, key=lambda x:sum(p[-1]<=rem for p in bycell[x]))
 for p in bycell[x]:
  ps=p[-1]
  if ps<=rem and (p[0]!='square' or sq<1):
   rec(rem-ps, chosen+[p], sq+(p[0]=='square'))
rec(cells,[],0)
print('all exact covers one square:',len(sol))
for s in sol[:10]:
 print([(p[:4]) for p in s])
# covers using only known missing corners TL,BL,TR
known={(1,1):2,(2,1):3,(1,2):4} # offset missing position
valid=[]
for s in sol:
 if all(p[0]!='L' or (p[3][0]-p[1],p[3][1]-p[2]) in known for p in s): valid.append(s)
print('known orientations only',len(valid))
for s in valid[:10]: print([(p[0],p[1],p[2],(p[3][0]-p[1],p[3][1]-p[2]) if p[0]=='L' else None) for p in s])
